package de.walahi.novosmp.clan;
import de.walahi.novosmp.NovoSMPPlugin;import de.walahi.smpcore.commands.framework.BaseCommand;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.util.List;
public final class ClanHomeCommand extends BaseCommand{public enum Mode{SET,GO,DELETE}private final ClanManager clans;private final Mode mode;public ClanHomeCommand(NovoSMPPlugin p,ClanManager c,Mode m){super(p);clans=c;mode=m;}protected String permission(){return "smpcore.clan.use";}protected boolean execute(CommandSender s,String l,String[] a){if(!(s instanceof Player p)){s.sendMessage("Nur für Spieler.");return true;}if(a.length!=1){clans.reply(p,"/"+l+" <Name>");return true;}clans.reply(p,switch(mode){case SET->clans.setHome(p,a[0]);case GO->clans.teleportHome(p,a[0]);case DELETE->clans.deleteHome(p,a[0]);});return true;}public List<String> onTabComplete(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p)||a.length!=1)return List.of();Clan clan=clans.clan(p.getUniqueId());return clan==null?List.of():clans.homes(clan).stream().map(ClanRepository.Home::display).filter(x->x.toLowerCase().startsWith(a[0].toLowerCase())).toList();}}
